"""Unrolled Fq12 kernels for SM9. Generated by tools/gen_sm9_fq12.py; do not edit.

An element is a tuple of twelve integers, the coefficients of 1, w, ..., w^11 in
Fq[w]/(w^12 + 2). Inputs may be any non-negative integers below a small multiple of
q; outputs are reduced to [0, q).
"""

from __future__ import annotations

Q = 0xB640000002A3A6F1D603AB4FF58EC74521F2934B1A7AEEDBE56F9B27E351457D


def mul(x: tuple, y: tuple) -> tuple:
    """Return x * y."""
    a0, a1, a2, a3, a4, a5, b0, b1, b2, b3, b4, b5 = x
    c0, c1, c2, c3, c4, c5, d0, d1, d2, d3, d4, d5 = y
    q = Q
    s0, s1, s2, s3, s4, s5 = a0 + b0, a1 + b1, a2 + b2, a3 + b3, a4 + b4, a5 + b5
    t0, t1, t2, t3, t4, t5 = c0 + d0, c1 + d1, c2 + d2, c3 + d3, c4 + d4, c5 + d5
    e0 = a0 * c0
    f0 = b0 * d0
    g0 = s0 * t0 - e0 - f0
    e1 = a0 * c1 + a1 * c0
    f1 = b0 * d1 + b1 * d0
    g1 = s0 * t1 + s1 * t0 - e1 - f1
    e2 = a0 * c2 + a1 * c1 + a2 * c0
    f2 = b0 * d2 + b1 * d1 + b2 * d0
    g2 = s0 * t2 + s1 * t1 + s2 * t0 - e2 - f2
    e3 = a0 * c3 + a1 * c2 + a2 * c1 + a3 * c0
    f3 = b0 * d3 + b1 * d2 + b2 * d1 + b3 * d0
    g3 = s0 * t3 + s1 * t2 + s2 * t1 + s3 * t0 - e3 - f3
    e4 = a0 * c4 + a1 * c3 + a2 * c2 + a3 * c1 + a4 * c0
    f4 = b0 * d4 + b1 * d3 + b2 * d2 + b3 * d1 + b4 * d0
    g4 = s0 * t4 + s1 * t3 + s2 * t2 + s3 * t1 + s4 * t0 - e4 - f4
    e5 = a0 * c5 + a1 * c4 + a2 * c3 + a3 * c2 + a4 * c1 + a5 * c0
    f5 = b0 * d5 + b1 * d4 + b2 * d3 + b3 * d2 + b4 * d1 + b5 * d0
    g5 = s0 * t5 + s1 * t4 + s2 * t3 + s3 * t2 + s4 * t1 + s5 * t0 - e5 - f5
    e6 = a1 * c5 + a2 * c4 + a3 * c3 + a4 * c2 + a5 * c1
    f6 = b1 * d5 + b2 * d4 + b3 * d3 + b4 * d2 + b5 * d1
    g6 = s1 * t5 + s2 * t4 + s3 * t3 + s4 * t2 + s5 * t1 - e6 - f6
    e7 = a2 * c5 + a3 * c4 + a4 * c3 + a5 * c2
    f7 = b2 * d5 + b3 * d4 + b4 * d3 + b5 * d2
    g7 = s2 * t5 + s3 * t4 + s4 * t3 + s5 * t2 - e7 - f7
    e8 = a3 * c5 + a4 * c4 + a5 * c3
    f8 = b3 * d5 + b4 * d4 + b5 * d3
    g8 = s3 * t5 + s4 * t4 + s5 * t3 - e8 - f8
    e9 = a4 * c5 + a5 * c4
    f9 = b4 * d5 + b5 * d4
    g9 = s4 * t5 + s5 * t4 - e9 - f9
    e10 = a5 * c5
    f10 = b5 * d5
    g10 = s5 * t5 - e10 - f10
    return (
        (e0 - 2 * f0 - 2 * g6) % q,
        (e1 - 2 * f1 - 2 * g7) % q,
        (e2 - 2 * f2 - 2 * g8) % q,
        (e3 - 2 * f3 - 2 * g9) % q,
        (e4 - 2 * f4 - 2 * g10) % q,
        (e5 - 2 * f5) % q,
        (g0 + e6 - 2 * f6) % q,
        (g1 + e7 - 2 * f7) % q,
        (g2 + e8 - 2 * f8) % q,
        (g3 + e9 - 2 * f9) % q,
        (g4 + e10 - 2 * f10) % q,
        (g5) % q,
    )


def sqr(x: tuple) -> tuple:
    """Return x * x; 2AB is computed as (A + B)^2 - A^2 - B^2."""
    a0, a1, a2, a3, a4, a5, b0, b1, b2, b3, b4, b5 = x
    q = Q
    s0, s1, s2, s3, s4, s5 = a0 + b0, a1 + b1, a2 + b2, a3 + b3, a4 + b4, a5 + b5
    da0, da1, da2, da3, da4 = a0 + a0, a1 + a1, a2 + a2, a3 + a3, a4 + a4
    db0, db1, db2, db3, db4 = b0 + b0, b1 + b1, b2 + b2, b3 + b3, b4 + b4
    ds0, ds1, ds2, ds3, ds4 = s0 + s0, s1 + s1, s2 + s2, s3 + s3, s4 + s4
    e0 = a0 * a0
    f0 = b0 * b0
    g0 = s0 * s0 - e0 - f0
    e1 = da0 * a1
    f1 = db0 * b1
    g1 = ds0 * s1 - e1 - f1
    e2 = da0 * a2 + a1 * a1
    f2 = db0 * b2 + b1 * b1
    g2 = ds0 * s2 + s1 * s1 - e2 - f2
    e3 = da0 * a3 + da1 * a2
    f3 = db0 * b3 + db1 * b2
    g3 = ds0 * s3 + ds1 * s2 - e3 - f3
    e4 = da0 * a4 + da1 * a3 + a2 * a2
    f4 = db0 * b4 + db1 * b3 + b2 * b2
    g4 = ds0 * s4 + ds1 * s3 + s2 * s2 - e4 - f4
    e5 = da0 * a5 + da1 * a4 + da2 * a3
    f5 = db0 * b5 + db1 * b4 + db2 * b3
    g5 = ds0 * s5 + ds1 * s4 + ds2 * s3 - e5 - f5
    e6 = da1 * a5 + da2 * a4 + a3 * a3
    f6 = db1 * b5 + db2 * b4 + b3 * b3
    g6 = ds1 * s5 + ds2 * s4 + s3 * s3 - e6 - f6
    e7 = da2 * a5 + da3 * a4
    f7 = db2 * b5 + db3 * b4
    g7 = ds2 * s5 + ds3 * s4 - e7 - f7
    e8 = da3 * a5 + a4 * a4
    f8 = db3 * b5 + b4 * b4
    g8 = ds3 * s5 + s4 * s4 - e8 - f8
    e9 = da4 * a5
    f9 = db4 * b5
    g9 = ds4 * s5 - e9 - f9
    e10 = a5 * a5
    f10 = b5 * b5
    g10 = s5 * s5 - e10 - f10
    return (
        (e0 - 2 * f0 - 2 * g6) % q,
        (e1 - 2 * f1 - 2 * g7) % q,
        (e2 - 2 * f2 - 2 * g8) % q,
        (e3 - 2 * f3 - 2 * g9) % q,
        (e4 - 2 * f4 - 2 * g10) % q,
        (e5 - 2 * f5) % q,
        (g0 + e6 - 2 * f6) % q,
        (g1 + e7 - 2 * f7) % q,
        (g2 + e8 - 2 * f8) % q,
        (g3 + e9 - 2 * f9) % q,
        (g4 + e10 - 2 * f10) % q,
        (g5) % q,
    )


def mul_line(x: tuple, l0: int, l2: int, l3: int, l6: int, l8: int, l9: int) -> tuple:
    """Return x times the sparse element l0 + l2 w^2 + l3 w^3 + l6 w^6 + l8 w^8 + l9 w^9."""
    a0, a1, a2, a3, a4, a5, b0, b1, b2, b3, b4, b5 = x
    q = Q
    s0, s1, s2, s3, s4, s5 = a0 + b0, a1 + b1, a2 + b2, a3 + b3, a4 + b4, a5 + b5
    c0, c2, c3, d0, d2, d3 = l0, l2, l3, l6, l8, l9
    t0, t2, t3 = c0 + d0, c2 + d2, c3 + d3
    e0 = a0 * c0
    f0 = b0 * d0
    g0 = s0 * t0 - e0 - f0
    e1 = a1 * c0
    f1 = b1 * d0
    g1 = s1 * t0 - e1 - f1
    e2 = a0 * c2 + a2 * c0
    f2 = b0 * d2 + b2 * d0
    g2 = s0 * t2 + s2 * t0 - e2 - f2
    e3 = a0 * c3 + a1 * c2 + a3 * c0
    f3 = b0 * d3 + b1 * d2 + b3 * d0
    g3 = s0 * t3 + s1 * t2 + s3 * t0 - e3 - f3
    e4 = a1 * c3 + a2 * c2 + a4 * c0
    f4 = b1 * d3 + b2 * d2 + b4 * d0
    g4 = s1 * t3 + s2 * t2 + s4 * t0 - e4 - f4
    e5 = a2 * c3 + a3 * c2 + a5 * c0
    f5 = b2 * d3 + b3 * d2 + b5 * d0
    g5 = s2 * t3 + s3 * t2 + s5 * t0 - e5 - f5
    e6 = a3 * c3 + a4 * c2
    f6 = b3 * d3 + b4 * d2
    g6 = s3 * t3 + s4 * t2 - e6 - f6
    e7 = a4 * c3 + a5 * c2
    f7 = b4 * d3 + b5 * d2
    g7 = s4 * t3 + s5 * t2 - e7 - f7
    e8 = a5 * c3
    f8 = b5 * d3
    g8 = s5 * t3 - e8 - f8
    return (
        (e0 - 2 * f0 - 2 * g6) % q,
        (e1 - 2 * f1 - 2 * g7) % q,
        (e2 - 2 * f2 - 2 * g8) % q,
        (e3 - 2 * f3) % q,
        (e4 - 2 * f4) % q,
        (e5 - 2 * f5) % q,
        (g0 + e6 - 2 * f6) % q,
        (g1 + e7 - 2 * f7) % q,
        (g2 + e8 - 2 * f8) % q,
        (g3) % q,
        (g4) % q,
        (g5) % q,
    )
